# Reciprocal Rank Fusion: 여러 검색기의 '순위'만 합친다 (k=60 이 관례)
def rrf(rankings, k=60, backlinks=None, bonus=0.0):
    score = {}
    for ranking in rankings:
        for r, doc in enumerate(ranking, start=1):
            score[doc] = score.get(doc, 0) + 1 / (k + r)
    for doc, n in (backlinks or {}).items():   # 많이 인용된 페이지 가산(가정)
        if doc in score:
            score[doc] += bonus * n
    return sorted(score.items(), key=lambda x: -x[1])

vector = ["A", "B", "C"]      # 임베딩 유사도 순위
bm25 = ["B", "D", "A"]        # 키워드(BM25) 순위
for doc, s in rrf([vector, bm25]):
    print(doc, round(s, 5))
print("-- 백링크 가산 후 --")
for doc, s in rrf([vector, bm25], backlinks={"A": 3}, bonus=0.0005):
    print(doc, round(s, 5))
